    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    from collections import deque
    queue = deque()
    visited = set()
    parent_map = {}
    queue.append(start)
    visited.add(start)
    parent_map[start] = None
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    while queue:
