def solve(n: int, edges: list[tuple[int, int, int]], s: int, t: int) -> int:
    """
    Compute the shortest path from s to t in a directed graph with integer weights.
    """
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))
    import heapq
    dist = [float('inf')] * n
    dist[s] = 0
    heap = [(0, s)]
    while heap:
        current_dist, u = heapq.heappop(heap)
        if current_dist > dist[u]:
            continue
        if u == t:
            return current_dist
        for v, w in graph[u]:
            if dist[v] > dist[u] + w:
                dist[v] = dist[u] + w
                heapq.heappush(heap, (dist[v], v))
    return -1 if dist[t] == float('inf') else dist[t]

